def is_prime(n):
    """Check if a number is prime"""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

n = int(input())
a = list(map(int, input().split()))

# Count the number of 1s and 2s
count_1 = a.count(1)
count_2 = a.count(2)

# Start with 2 if we have any
result = []
if count_2 > 0:
    result.append(2)
    count_2 -= 1

# Try to add numbers to keep the sum prime
while count_1 > 0 or count_2 > 0:
    # Try adding 1 first
    if count_1 > 0:
        next_sum = result[-1] + 1 if result else 1
        if is_prime(next_sum):
            result.append(1)
            count_1 -= 1
            continue

    # If adding 1 doesn't work, try adding 2
    if count_2 > 0:
        next_sum = result[-1] + 2 if result else 2
        if is_prime(next_sum):
            result.append(2)
            count_2 -= 1
            continue

    # If neither works, we have to add the one that keeps the sum prime
    # This shouldn't happen if we have at least one number left
    if count_1 > 0:
        result.append(1)
    else:
        result.append(2)

print(' '.join(map(str, result)))
