def longest_path(start, current_path, visited, graph, max_length):
    """Backtrack to find the longest path starting from 'start'"""

    # Update max_length if we found a longer path
    if len(current_path) > max_length[0]:
        max_length[0] = len(current_path)

    # Try to extend the path from 'start'
    for neighbor in graph[start]:
        if not visited[neighbor]:
            visited[neighbor] = True
            current_path.append(neighbor)

            # Recursively explore from the neighbor
            longest_path(neighbor, current_path, visited, graph, max_length)

            # Backtrack
            current_path.pop()
            visited[neighbor] = False


def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        # Read the graph
        graph = {}
        for _ in range(n):
            a, b = map(int, input().split())
            if a not in graph:
                graph[a] = []
            if b not in graph:
                graph[b] = []
            graph[a].append(b)
            graph[b].append(a)

        # Find the longest path
        max_length = [0]
        visited = {node: False for node in graph}

        # Try all possible starting nodes
        for start in graph:
            visited[start] = True
            current_path = [start]
            longest_path(start, current_path, visited, graph, max_length)
            visited[start] = False
            current_path = []

        print(max_length[0])

solve()
