def solve():
    n, m, k = map(int, input().split())

    # Memoization dictionary for Grundy numbers
    memo = {}

    def grundy(length):
        if length < k:
            return 0
        if length in memo:
            return memo[length]

        # Try all possible splits
        reachable = set()

        # Try all possible numbers of parts t
        # t must be > 1 and length/t >= k
        # So t can be any divisor of length such that t > 1 and length/t >= k

        # Try all possible t from 2 to length
        for t in range(2, length + 1):
            if length % t == 0:
                part_length = length // t
                if part_length >= k:
                    # Split into t parts of length part_length
                    # Grundy number = XOR of t copies of grundy(part_length)
                    g = grundy(part_length)
                    xor_result = 0
                    for _ in range(t):
                        xor_result ^= g
                    reachable.add(xor_result)

        # Find mex (minimum excludant)
        mex = 0
        while mex in reachable:
            mex += 1

        memo[length] = mex
        return mex

    # Each log has grundy number g = grundy(m)
    # With n logs, the total Grundy number is XOR of n copies of g
    g = grundy(m)
    total = 0
    for _ in range(n):
        total ^= g

    if total != 0:
        print("Timur")
    else:
        print("Marsel")

solve()
