import sys

def solve():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    results = []

    for i in range(1, t + 1):
        s = data[i]
        freq = {}
        for ch in s:
            freq[ch] = freq.get(ch, 0) + 1

        # We want to keep the rightmost occurrence of each character that appears multiple times
        # So we iterate from 'z' to 'a'
        # And for each character, we want to keep one occurrence (the rightmost one)

        # First, determine which characters we want to keep
        keep = set()
        for ch in reversed(freq):
            if freq[ch] > 1:
                keep.add(ch)

        # Now build the result by keeping characters that are in 'keep' set
        # But we need to keep the rightmost occurrence of each character
        # So we iterate from right to left and keep the first occurrence of each character
        result = []
        for ch in reversed(s):
            if ch in keep and ch not in result:
                result.append(ch)

        result.reverse()
        results.append(''.join(result))

    sys.stdout.write('\n'.join(results))

if __name__ == '__main__':
    solve()
"}

