    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    w = [0] * n
    for i in range(n):
        w[i] = int(data[idx]); idx += 1

    friends = []
    for i in range(m):
        x = int(data[idx]) - 1; idx += 1
        y = int(data[idx]) - 1; idx += 1
        friends.append((x, y, i))

    # Priority: 0 for friends who have one favorite with 0 plates
    #          1 for friends who have both favorites with 0 plates
    #          2 for friends who have both favorites with >0 plates
    priorities = [0] * m
    for i in range(m):
        x, y, _ = friends[i]
        if w[x] == 0 or w[y] == 0:
            priorities[i] = 0
        elif w[x] == 0 and w[y] == 0:
            priorities[i] = 1
        else:
            priorities[i] = 2

    # Sort by priority (0 < 1 < 2), then by index to break ties
    friends.sort(key=lambda f: (priorities[f[2]], f[2]))

    # Call friends in this order
    order = [f[2] + 1 for f in friends]

    # Check if this order works
    for x, y, _ in friends:
        if w[x] == 0 and w[y] == 0:
            # This friend eats Lee
            print("DEAD")
            return
        else:
            # This friend eats at least one plate
            if w[x] > 0:
                w[x] -= 1
            if w[y] > 0:
                w[y] -= 1

    print("ALIVE")
    print(' '.join(map(str, order)))

if __name__ == "__main__":
    solve()
