def solve():
    d, n = map(int, input().split())
    a = list(map(int, input().split()))

    # Build tree
    tree = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        tree[u - 1].append(v - 1)
        tree[v - 1].append(u - 1)

    # dp[u][k] = number of valid sets in subtree rooted at u with sum exactly k
    dp = [{} for _ in range(n)]

    def dfs(u, parent):
        # Base case: leaf node (no children except parent)
        if len(tree[u]) == 1 and tree[u][0] == parent:
            # Can take empty set or just node u
            dp[u][0] = 1
            if a[u] <= d:
                dp[u][a[u]] = 1
            return

        # Combine results from children
        for v in tree[u]:
            if v != parent:
                dfs(v, u)

        # Combine sets from different children
        for i in range(len(tree[u])):
            v = tree[u][i]
            if v != parent:
                # Combine with sets from other children
                for j in range(i + 1, len(tree[u])):
                    w = tree[u][j]
                    if w != parent:
                        # Combine sets from child v and child w
                        for s in dp[v]:
                            for t in dp[w]:
                                if s + t <= d:
                                    dp[u][s + t] = (dp[u].get(s + t, 0) + dp[v][s] * dp[w][t]) % MOD

                # Combine with sets from other children through u
                for s in dp[v]:
                    if s + a[u] <= d:
                        dp[u][s + a[u]] = (dp[u].get(s + a[u], 0) + dp[v][s]) % MOD

    dfs(0, -1)

    # Sum all valid sets in the whole tree
    result = 0
    for k in dp[0]:
        if k <= d:
            result = (result + dp[0][k]) % MOD

    print(result)

solve()
