    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    Q = int(next(it))

    # Dictionary to map prefixes to list of words
    prefix_map = {}

    # Read N words
    for _ in range(N):
        word = next(it)
        # Add to prefix map
        for i in range(1, len(word) + 1):
            prefix = word[:i]
            if prefix not in prefix_map:
                prefix_map[prefix] = []
            prefix_map[prefix].append(word)

    # Process Q queries
    for _ in range(Q):
        p = next(it)
        s = next(it)

        # Get words with this prefix
        if p not in prefix_map:
            print(0)
            continue

        count = 0
        for word in prefix_map[p]:
            if word.endswith(s):
                count += 1

        print(count)

if __name__ == "__main__":
    solve()
