V, E, K = map(int, input().split())

# Build adjacency list
adj = [[] for _ in range(V)]
for _ in range(E):
    v1, v2, c = map(int, input().split())
    adj[v1].append((v2, c))

# max_score[v][n] = maximum score at cone v with exactly n arrows
max_score = [[-1] * 101 for _ in range(V)]
parent = [[None] * 101 for _ in range(V)]

# Initialize: score 0 at each cone with 0 arrows
for v in range(V):
    max_score[v][0] = 0
    parent[v][0] = -1  # No parent for start

# BFS to find maximum scores
from collections import deque

queue = deque()
for v in range(V):
    queue.append((v, 0))

while queue:
    v, n = queue.popleft()

    if n >= 100:
        continue

    if max_score[v][n] == -1:
        continue

    for u, c in adj[v]:
        new_n = n + 1
        new_score = max_score[v][n] + c

        if new_score > max_score[u][new_n]:
            max_score[u][new_n] = new_score
            parent[u][new_n] = (v, n)
            queue.append((u, new_n))

# Find the minimum number of arrows
min_arrows = -1
for v in range(V):
    for n in range(101):
        if max_score[v][n] >= K:
            min_arrows = n
            break
    if min_arrows != -1:
        break

if min_arrows == -1:
    print(-1)
else:
    print(min_arrows)

    # Reconstruct path if min_arrows ≤ 100
    if min_arrows <= 100:
        path = []
        v, n = v, min_arrows
        while n >= 0:
            path.append(v)
            v, n = parent[v][n]
        path.reverse()
        print(' '.join(map(str, path)))
"}

