def find_suffixes(s):
    n = len(s)
    suffixes = set()

    # Try each possible root length (must be at least 5)
    for root_len in range(5, n):
        # The remaining string after the root
        remaining = s[root_len:]

        # Find all suffixes that can be formed from the remaining string
        # We need to split remaining into parts of length 2 or 3, no consecutive duplicates

        # Use dynamic programming to find all valid suffixes
        # dp[i] = set of suffixes that can be formed from the last i characters
        dp = [set() for _ in range(len(remaining) + 1)]
        dp[0].add(None)  # Base case: empty string

        for i in range(1, len(remaining) + 1):
            # Try taking a suffix of length 2
            if i >= 2:
                suffix = remaining[i-2:i]
                for prev_suffix in dp[i-2]:
                    if prev_suffix != suffix:
                        dp[i].add(suffix)

            # Try taking a suffix of length 3
            if i >= 3:
                suffix = remaining[i-3:i]
                for prev_suffix in dp[i-3]:
                    if prev_suffix != suffix:
                        dp[len(remaining)].add(suffix)

        # Collect all suffixes from this root
        suffixes.update(dp[len(remaining)])

    return sorted(suffixes)

