def solve():
    n, k, A, B = map(int, input().split())
    positions = list(map(int, input().split()))

    # Create a set of positions for quick lookup
    avengers = set(positions)

    # Length of the base
    length = 1 << n  # 2^n

    # DP: dp[l][r] = minimum power to destroy segment [l, r]
    # We'll use memoization with lru_cache
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(l, r):
        # Length of the segment
        seg_len = r - l + 1

        # Count avengers in this segment
        count = 0
        for pos in positions:
            if l <= pos <= r:
                count += 1

        # Option 1: Burn
        if count == 0:
            cost_burn = A
        else:
            cost_burn = B * count * seg_len

        # Option 2: Divide (if length >= 2)
        if seg_len >= 2:
            mid = (l + r) // 2
            cost_divide = dp(l, mid) + dp(mid + 1, r)
            return min(cost_burn, cost_divide)
        else:
            return cost_burn

    result = dp(1, length)
    print(result)

solve()
