def cross_product(a, b):
    """Calculate cross product of vectors a and b"""
    return a[0] * b[1] - a[1] * b[0]

def dot_product(a, b):
    """Calculate dot product of vectors a and b"""
    return a[0] * b[0] + a[1] * b[1]

def vector_length_sq(v):
    """Calculate squared length of vector v"""
    return v[0] * v[0] + v[1] * v[1]

def angle_between(v1, v2):
    """Calculate angle between vectors v1 and v2 in degrees"""
    cos_theta = dot_product(v1, v2) / (vector_length_sq(v1) ** 0.5 * vector_length_sq(v2) ** 0.5)
    # Clamp to avoid numerical issues
    cos_theta = max(min(cos_theta, 1.0), -1.0)
    return math.degrees(math.acos(cos_theta))

def segment_intersection(seg1, seg2):
    """Check if segments seg1 and seg2 intersect and return intersection point"""
    # seg1: (x1, y1, x2, y2)
    # seg2: (x3, y3, x4, y4)
    x1, y1, x2, y2 = seg1
    x3, y3, x4, y4 = seg2

    # Calculate denominator
    denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if denom == 0:
        return None  # Parallel or collinear

    # Calculate t and u
    t_num = (x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)
    t = t_num / denom
    u_num = (x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)
    u = u_num / denom

    # Check if intersection is within segments
    if 0 <= t <= 1 and 0 <= u <= 1:
        # Intersection point
        x = x1 + t * (x2 - x1)
        y = y1 + t * (y2 - y1)
