def shortest_supersequence(strings):
    n = len(strings)

    # dp[mask][i] = minimum length of supersequence for strings included in mask, ending with character at position i
    # We'll use a dictionary for efficiency
    dp = {}

    # Initialize: no strings included, result is empty
    dp[0] = {i: 0 for i in range(len(strings))}  # For each string, we can start with it

    for mask in range(1, 1 << n):
        # For each string that can be added to this mask
        for i in range(n):
            if not (mask & (1 << i)):
                # Try adding string i to the supersequence
                new_mask = mask | (1 << i)

                # For each possible ending position in the current supersequence
                for end_pos in dp[mask]:
                    # For each possible starting position in string i
                    for start_pos in range(len(strings[i])):
                        # Try appending characters from string i starting at start_pos
                        # The new supersequence ends at position start_pos + len(strings[i]) - 1
                        new_end_pos = start_pos + len(strings[i]) - 1

                        # Update dp[new_mask] with the new length
                        new_length = dp[mask][end_pos] + len(strings[i])

                        if new_end_pos not in dp[new_mask] or new_length < dp[new_mask][new_end_pos]:
                            dp[new_mask][new_end_pos] = new_length

    # Find the minimum length for all strings included
    return min(dp[(1 << n) - 1].values())

