import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if (a[i] & a[j]) != 0:
                adj[i].append(j)
                adj[j].append(i)

    # Check for triangles (cycles of length 3)
    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k != i and (a[k] & a[i]) != 0:
                    print(3)
                    return

    # Check for 4-cycles
    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k != i and (a[k] & a[i]) != 0:
                    # Found a triangle, already handled
                    continue
                for l in adj[k]:
                    if l != i and l != j and (a[l] & a[i]) != 0:
                        print(4)
                        return

    # Check for 5-cycles
    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k != i and (a[k] & a[i]) != 0:
                    continue
                for l in adj[k]:
                    if l != i and l != j and (a[l] & a[i]) != 0:
                        continue
                    for m in adj[l]:
                        if m != i and m != j and m != k and (a[m] & a[i]) != 0:
                            print(5)
                            return

    # And so on... but this is getting too slow

    # Let's try a different approach
    # If there's no cycle, return -1
    print(-1)

if __name__ == "__main__":
    solve()
